The ideal solution consists of the following key changes:

1.  **`config/app_config.json`:**
    ```diff
    --- a/config/app_config.json
    +++ b/config/app_config.json
    @@ -4,7 +4,8 @@
       "database": {
         "path": "./data/flowframe.db"
       },
    -  "window": {
    +  "syncMode": "on_startup", // Can be "on_startup" or "manual"
    +  "window": {
         "width": 1280,
         "height": 720
       }
    ```

2.  **A shared header (e.g., `src/core/app_context.h`, or `main.c` if no context header exists):**
    ```c
    // New Enum Definition
    typedef enum {
        SYNC_MODE_ON_STARTUP,
        SYNC_MODE_MANUAL
    } AppSyncMode;

    // Added to a global AppContext struct
    typedef struct {
        // ... other settings
        AppSyncMode sync_mode;
    } AppContext;
    ```

3.  **`src/main.c` (Config Parsing):**
    ```c
    // Inside config parsing function
    const char* sync_mode_str = json_object_get_string(root, "syncMode");
    if (sync_mode_str && strcmp(sync_mode_str, "manual") == 0) {
        g_app_context.sync_mode = SYNC_MODE_MANUAL;
    } else {
        g_app_context.sync_mode = SYNC_MODE_ON_STARTUP; // Default
    }
    ```

4.  **`src/main.c` (Service Initialization):**
    ```c
    // Pass the mode to the service
    sync_service_init(g_app_context.sync_mode);
    ```

5.  **`src/services/sync_service.h`:**
    ```c
    // Modified init function and new trigger function
    void sync_service_init(AppSyncMode mode);
    void sync_service_trigger_manual_sync(void);
    ```

6.  **`src/services/sync_service.c`:**
    ```c
    static bool is_syncing = false;

    void sync_service_init(AppSyncMode mode) {
        // ... other initialization ...
        if (mode == SYNC_MODE_ON_STARTUP) {
            start_sync_process(); // internal function
        }
    }

    void sync_service_trigger_manual_sync(void) {
        if (!is_syncing) {
            start_sync_process();
        }
    }
    ```

7.  **`src/main.c` (Keyboard Handling):**
    ```c
    // In main event loop
    if (event.type == KEY_PRESS && event.key.code == 's' && event.key.control) {
        sync_service_trigger_manual_sync();
    }
    ```
